class LineComplete(ShellComplete):
    """Shell completion for Bash's ``complete -C`` protocol. The raw command
    line is read from ``COMP_LINE`` and the cursor offset from
    ``COMP_POINT``. One plain candidate is printed per line.

    .. versionadded:: 8.6.0
    """

    name: t.ClassVar[str] = "line"
    source_template: t.ClassVar[str] = _SOURCE_LINE

    def _parse_request(self) -> tuple[list[str], str]:
        """Return all complete words (including the program word) and the
        incomplete word, based on ``COMP_LINE`` and ``COMP_POINT``.
        """
        if "COMP_LINE" not in os.environ:
            raise CompletionRequestError(_("COMP_LINE is not set."))

        line = os.environ["COMP_LINE"]
        raw_point = os.environ.get("COMP_POINT", "")

        if not raw_point:
            point = len(line)
        elif re.fullmatch(r"[0-9]+", raw_point) is None:
            raise CompletionRequestError(
                _(
                    "Invalid COMP_POINT value {value!r}: expected a"
                    " non-negative integer."
                ).format(value=raw_point)
            )
        else:
            point = int(raw_point)

            if point > len(line):
                raise CompletionRequestError(
                    ngettext(
                        "COMP_POINT {point} is past the end of COMP_LINE"
                        " ({length} character).",
                        "COMP_POINT {point} is past the end of COMP_LINE"
                        " ({length} characters).",
                        len(line),
                    ).format(point=point, length=len(line))
                )

        text = line[:point]
        words = split_arg_string(text)

        # If the text ends in free (unquoted, unescaped) whitespace, a
        # following character starts a new word. Otherwise it extends the
        # last word, which is then the incomplete one.
        if not words or len(split_arg_string(f"{text}_")) > len(words):
            return words, ""

        return words[:-1], words[-1]

    def get_completion_args(self) -> tuple[list[str], str]:
        words, incomplete = self._parse_request()
        return words[1:], incomplete

    def format_completion(self, item: CompletionItem[t.Any]) -> str:
        return str(item.value)

    def complete(self) -> str:
        words, incomplete = self._parse_request()

        # The first complete word is the program name. Without it there is
        # nothing to resolve.
        if not words:
            return ""

        completions = self.get_completions(words[1:], incomplete)
        out = []

        for item in completions:
            if item.type != "plain":
                continue

            value = self.format_completion(item)

            if "\n" in value or "\r" in value:
                continue

            out.append(f"{value}\n")

        return "".join(out)


