    def paint(color, secret, path):
        pass

    @cli.command()
    def status():
        pass

    @cli.command(hidden=True)
    def secret():
        pass

    return cli


def _echo_cli():
    @click.command()
    @click.argument(
        "words",
        nargs=-1,
        shell_complete=lambda ctx, param, incomplete: [f"got:{incomplete}"],
    )
    def cli(words):
        pass

    return cli


def _complete(runner, cli, line, point=None, prog_name="tool", **extra):
    env = {
        "_TOOL_COMPLETE": "line_complete",
        "COMP_LINE": line,
        "COMP_POINT": point,
    }
    return runner.invoke(cli, env=env, prog_name=prog_name, **extra)


def test_public_names_and_registration():
    from click.shell_completion import CompletionRequestError
    from click.shell_completion import get_completion_class
    from click.shell_completion import LineComplete
    from click.shell_completion import ShellComplete

    assert get_completion_class("line") is LineComplete
    assert issubclass(LineComplete, ShellComplete)
    assert LineComplete.name == "line"
    assert LineComplete.source_template == (
        "complete -o default -o nosort -C"
        " '%(complete_var)s=line_complete %(prog_name)s' %(prog_name)s\n"
    )
    assert issubclass(CompletionRequestError, click.ClickException)
    err = CompletionRequestError("boom")
    assert err.exit_code == 1
    assert err.message == "boom"


def test_subcommands_completed_at_end_of_line_hidden_excluded(runner):
    result = _complete(runner, _paint_cli(), "tool ", "5")
    assert result.exit_code == 0
    assert result.stdout == "paint\nstatus\n"
    assert result.stderr == ""


def test_option_value_with_equals_prints_bare_value(runner):
    result = _complete(runner, _paint_cli(), "tool paint --color=r")
    assert result.exit_code == 0
    assert result.stdout == "red\nrose\n"


@pytest.mark.parametrize("point", ["7", "007"])
def test_comp_point_truncates_line(runner, point):
    result = _complete(runner, _paint_cli(), "tool st --help", point)
    assert result.exit_code == 0
    assert result.stdout == "status\n"


@pytest.mark.parametrize("point", [None, "", "7"])
def test_unset_or_empty_point_means_end_of_line(runner, point):
    result = _complete(runner, _paint_cli(), "tool st", point)
    assert result.exit_code == 0
    assert result.stdout == "status\n"


def test_missing_comp_line_is_reported_before_point(runner):
    result = _complete(runner, _paint_cli(), None, "abc")
    assert result.exit_code == 1
    assert result.stdout == ""
    assert result.stderr == "Error: COMP_LINE is not set.\n"


@pytest.mark.parametrize("point", ["-1", "+3", " 3", "3 ", "1.0", "abc", "0x2"])
def test_invalid_comp_point_value(runner, point):
    result = _complete(runner, _paint_cli(), "tool st", point)
    assert result.exit_code == 1
    assert result.stdout == ""
    assert result.stderr == (
        f"Error: Invalid COMP_POINT value {point!r}:"
        " expected a non-negative integer.\n"
    )


@pytest.mark.parametrize(
    ("line", "point", "message"),
    [
        ("tool st", "12", "COMP_POINT 12 is past the end of COMP_LINE (7 characters)."),
        ("t", "0002", "COMP_POINT 2 is past the end of COMP_LINE (1 character)."),
        ("", "1", "COMP_POINT 1 is past the end of COMP_LINE (0 characters)."),
    ],
)
def test_comp_point_past_end_of_line(runner, line, point, message):
    result = _complete(runner, _paint_cli(), line, point)
    assert result.exit_code == 1
    assert result.stdout == ""
    assert result.stderr == f"Error: {message}\n"


@pytest.mark.parametrize(
