)
def test_no_complete_words_prints_nothing(runner, line, point):
    result = _complete(runner, _paint_cli(), line, point)
    assert result.exit_code == 0
    assert result.stdout == ""
    assert result.stderr == ""


def test_program_word_is_not_checked(runner):
    result = _complete(runner, _paint_cli(), "./bin/other-name st")
    assert result.exit_code == 0
    assert result.stdout == "status\n"


@pytest.mark.parametrize(
    ("line", "expected"),
    [
        ("tool pa", "got:pa\n"),
        ("tool pa ", "got:\n"),
        ("tool pa\t", "got:\n"),
        ("tool 'my ", "got:my \n"),
        ("tool my\\ ", "got:my \n"),
        ("tool ''", "got:\n"),
        ('tool "a b"', "got:a b\n"),
    ],
)
def test_tokenisation_of_incomplete_word(runner, line, expected):
    result = _complete(runner, _echo_cli(), line)
    assert result.exit_code == 0
    assert result.stdout == expected


def test_output_keeps_only_single_line_plain_items(runner):
    def complete_items(ctx, param, incomplete):
        return [
            CompletionItem("alpha", help="first item"),
            CompletionItem("f", type="file"),
            CompletionItem("x\ny"),
            CompletionItem("c\rd"),
            CompletionItem(42),
            CompletionItem("d", type="dir"),
            CompletionItem("it's \"here\"", type="plain"),
        ]

    @click.command()
    @click.argument("value", shell_complete=complete_items)
    def cli(value):
        pass

    result = _complete(runner, cli, "tool ")
    assert result.exit_code == 0
    assert result.stdout == "alpha\n42\nit's \"here\"\n"


def test_path_completion_yields_empty_stdout(runner):
    result = _complete(runner, _paint_cli(), "tool paint 'my ")
    assert result.exit_code == 0
    assert result.stdout == ""
    assert result.stderr == ""


def test_option_names_hidden_repeated_and_double_dash(runner):
    cli = _paint_cli()
    result = _complete(runner, cli, "tool paint --")
    assert result.exit_code == 0
    assert result.stdout == "--color\n--help\n"

    result = _complete(runner, cli, "tool paint --color red --")
    assert result.exit_code == 0
    assert result.stdout == "--help\n"

    result = _complete(runner, cli, "tool paint -- --")
    assert result.exit_code == 0
    assert result.stdout == ""


def test_chained_group_and_forwarded_context_kwargs(runner):
    @click.group(chain=True)
    def cli():
        pass

    @cli.command()
    def a():
        pass

    @cli.command()
