def test_line_source_prints_template(runner):
    cli = _paint_cli()
    result = runner.invoke(
        cli,
        ["ignored", "args"],
        env={"_TOOL_COMPLETE": "line_source", "COMP_LINE": None, "COMP_POINT": "x"},
        prog_name="tool",
    )
    assert result.exit_code == 0
    assert result.stdout == (
        "complete -o default -o nosort -C '_TOOL_COMPLETE=line_complete tool' tool\n"
    )

    result = runner.invoke(
        cli,
        env={"_MY_VAR": "line_source"},
        prog_name="my-tool",
        complete_var="_MY_VAR",
    )
    assert result.exit_code == 0
    assert result.stdout == (
        "complete -o default -o nosort -C '_MY_VAR=line_complete my-tool' my-tool\n"
    )


def test_unknown_line_instruction_exits_with_1(runner):
    result = runner.invoke(
        _paint_cli(),
        env={"_TOOL_COMPLETE": "line_bogus", "COMP_LINE": "tool "},
        prog_name="tool",
    )
    assert result.exit_code == 1
    assert result.stdout == ""
    assert result.stderr == ""


def test_request_error_from_custom_shell_class(runner):
    from click.shell_completion import add_completion_class
    from click.shell_completion import CompletionRequestError
    from click.shell_completion import ShellComplete

    class StrictComplete(ShellComplete):
        name = "strictsh"
        source_template = "unused"

        def source(self):
            raise CompletionRequestError("cannot source here")

        def get_completion_args(self):
            raise CompletionRequestError("bad request")

        def format_completion(self, item):
            return item.value

    add_completion_class(StrictComplete)
    cli = _paint_cli()

    result = runner.invoke(
        cli, env={"_TOOL_COMPLETE": "strictsh_complete"}, prog_name="tool"
    )
    assert result.exit_code == 1
    assert result.stdout == ""
    assert result.stderr == "Error: bad request\n"

    result = runner.invoke(
        cli, env={"_TOOL_COMPLETE": "strictsh_source"}, prog_name="tool"
    )
    assert result.exit_code == 1
    assert result.stdout == ""
    assert result.stderr == "Error: cannot source here\n"
